trait Shape {
    fn area(&self) -> f64;
}

struct Circle {
    radius: f64,
}

struct Rectangle {
    w: f64,
    h: f64,
}

fn main() {}

exercises.solution:
trait Shape {
    fn area(&self) -> f64;
}

struct Circle {
    radius: f64,
}

struct Rectangle {
    w: f64,
    h: f64,
}

impl Shape for Circle {
    fn area(&self) -> f64 {
        std::f64::consts::PI * self.radius * self.radius
    }
}

impl Shape for Rectangle {
    fn area(&self) -> f64 {
        self.w * self.h
    }
}

fn main() {
    let c = Circle { radius: 5.0 };
    let r = Rectangle { w: 3.0, h: 4.0 };
    let a1 = c.area();
    let a2 = r.area();
    println!("{}", a1.max(a2));
}

