exercises.solution:
trait Describable {
    fn name(&self) -> &str;
}

struct Person {
    name: String,
}

impl Describable for Person {
    fn name(&self) -> &str {
        &self.name
    }
}

fn main() {
    let p = Person {
        name: "Alice".into(),
    };
    let d: &dyn Describable = &p;
    println!("{}", d.name());
}

