exercises.solution:
enum Any {
    Int(i32),
    Str(&'static str),
}

fn describe(a: Any) {
    match a {
        Any::Int(v) => println!("int: {}", v),
        Any::Str(v) => println!("string: {}", v),
    }
}

fn main() {
    describe(Any::Int(42));
    describe(Any::Str("hello"));
}

exercises.starter_code:
trait Speaker {
    fn speak(&self) -> &'static str;
}

struct Dog;
struct Cat;

fn main() {}

exercises.solution:
trait Speaker {
    fn speak(&self) -> &'static str;
}

struct Dog;
struct Cat;

impl Speaker for Dog {
    fn speak(&self) -> &'static str {
        "Woaf"
    }
}

impl Speaker for Cat {
    fn speak(&self) -> &'static str {
        "Mew"
    }
}

fn main() {
    let speakers: Vec<Box<dyn Speaker>> = vec![Box::new(Dog), Box::new(Cat)];
    for s in speakers {
        println!("{}", s.speak());
    }
}

