enum Item {
    Int(i32),
    Str(&'static str),
    Float(f64),
}

fn main() {
    let items = vec![Item::Int(42), Item::Str("hello"), Item::Float(3.14)];
    for it in items {
        match it {
            Item::Int(v) => println!("int: {}", v),
            Item::Str(v) => println!("string: {}", v),
            Item::Float(v) => println!("float64: {:.2}", v),
        }
    }
}
